package ai.meshkit.core

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import java.io.File
import java.util.Base64
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Proves byte-level wire compatibility against golden vectors generated by
 * the Swift SDK (`scripts/wire_vectors_gen` -> vectors/wire-compat.v1.json).
 * Canonical strings, hashes, and signing inputs must match byte for byte.
 * Signatures cannot be compared byte-wise — CryptoKit emits randomized
 * Ed25519 signatures (unlike RFC 8032 pure/deterministic JCA) — so the
 * cross-implementation proof is mutual verification over identical signing
 * inputs: Kotlin must verify the Swift signatures, and Kotlin's own
 * signatures must verify under the Swift-exported raw public keys.
 */
class WireCompatVectorsTest {

    private data class Vectors(
        val requestSeed: ByteArray,
        val requestPublicKeyBase64: String,
        val receiptSeed: ByteArray,
        val receiptPublicKeyBase64: String,
        val receiptKeyId: String,
        val cases: List<VectorCase>
    )

    private data class VectorCase(
        val name: String,
        val requestEnvelopeBase64: String,
        val canonicalPayload: String,
        val canonicalPayloadNonceBound: String,
        val payloadHashPlain: String,
        val payloadHashNonceBound: String,
        val requestSigningInput: String,
        val requestSignatureBase64: String,
        val receiptEnvelopeBase64: String,
        val receiptSigningInput: String,
        val receiptCanonicalResult: String,
        val receiptSignatureBase64: String
    )

    private val vectors: Vectors by lazy {
        val path = System.getProperty("meshkit.vectors")
            ?: "../vectors/wire-compat.v1.json"
        val root = Json.parseToJsonElement(File(path).readText()).jsonObject
        fun str(key: String) = root.getValue(key).jsonPrimitive.content
        Vectors(
            requestSeed = str("requestSignerSeedHex").hexToBytes(),
            requestPublicKeyBase64 = str("requestSignerPublicKeyBase64"),
            receiptSeed = str("receiptSignerSeedHex").hexToBytes(),
            receiptPublicKeyBase64 = str("receiptSignerPublicKeyBase64"),
            receiptKeyId = str("receiptSignerKeyId"),
            cases = root.getValue("cases").jsonArray.map { case ->
                val obj = case.jsonObject
                fun cs(key: String) = obj.getValue(key).jsonPrimitive.content
                VectorCase(
                    name = cs("name"),
                    requestEnvelopeBase64 = cs("requestEnvelopeBase64"),
                    canonicalPayload = cs("canonicalPayload"),
                    canonicalPayloadNonceBound = cs("canonicalPayloadNonceBound"),
                    payloadHashPlain = cs("payloadHashPlain"),
                    payloadHashNonceBound = cs("payloadHashNonceBound"),
                    requestSigningInput = cs("requestSigningInput"),
                    requestSignatureBase64 = cs("requestSignatureBase64"),
                    receiptEnvelopeBase64 = cs("receiptEnvelopeBase64"),
                    receiptSigningInput = cs("receiptSigningInput"),
                    receiptCanonicalResult = cs("receiptCanonicalResult"),
                    receiptSignatureBase64 = cs("receiptSignatureBase64")
                )
            }
        )
    }

    private fun String.hexToBytes(): ByteArray =
        chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    @Test
    fun `derived public keys match the Swift signer keys`() {
        // JCA has no raw-public-key export shortcut, so prove key equivalence
        // behaviorally: a signature made from the seed verifies under the
        // Swift-exported raw public key.
        val probe = "meshkit-key-equivalence-probe".toByteArray()
        val requestSignature = Ed25519Jvm.signerFromSeed(vectors.requestSeed).sign(probe)
        assertTrue(
            Ed25519Jvm.rawKeyVerifier.verify(
                probe, requestSignature, Base64.getDecoder().decode(vectors.requestPublicKeyBase64)
            )
        )
        val receiptSignature = Ed25519Jvm.signerFromSeed(vectors.receiptSeed).sign(probe)
        assertTrue(
            Ed25519Jvm.rawKeyVerifier.verify(
                probe, receiptSignature, Base64.getDecoder().decode(vectors.receiptPublicKeyBase64)
            )
        )
    }

    @Test
    fun `request vectors reproduce canonical forms hashes signing inputs and signatures`() {
        for (case in vectors.cases) {
            val request = MeshRequest.decodedFromEnvelope(case.requestEnvelopeBase64)

            assertEquals(case.canonicalPayload, MeshRequestPayloadHasher.canonicalString(request.payload), case.name)
            assertEquals(
                case.canonicalPayloadNonceBound,
                MeshRequestPayloadHasher.canonicalString(request.payload, request.nonce),
                case.name
            )
            assertEquals(case.payloadHashPlain, MeshRequestPayloadHasher.sha256Hex(request.payload), case.name)
            assertEquals(
                case.payloadHashNonceBound,
                MeshRequestPayloadHasher.sha256Hex(request.payload, request.nonce),
                case.name
            )
            assertEquals(case.payloadHashNonceBound, request.payloadHash.value, case.name)
            assertEquals(case.requestSigningInput, request.signingInput(), case.name)

            // Kotlin signature over the same signing input verifies under the
            // Swift-exported raw public key.
            val resigned = MeshSignedRequestCrypto.sign(
                request.copy(signature = MeshSignature("Ed25519", request.signature.keyId, "")),
                Ed25519Jvm.signerFromSeed(vectors.requestSeed),
                keyId = request.signature.keyId
            )
            assertEquals(case.requestSigningInput, resigned.signingInput(), case.name)
            assertTrue(
                Ed25519Jvm.rawKeyVerifier.verify(
                    resigned.signingInputData(),
                    Base64.getDecoder().decode(resigned.signature.value),
                    Base64.getDecoder().decode(vectors.requestPublicKeyBase64)
                ),
                case.name
            )

            // And the Swift-shipped signature verifies under the trust metadata path.
            MeshTarget.verifyRequiredSignature(
                request,
                MeshSenderTrust(
                    callerAppId = request.caller.appId,
                    callerBundleId = request.caller.bundleId,
                    requestSigningAlgorithm = "Ed25519",
                    requestSigningKeyId = request.signature.keyId,
                    publicKeyBase64 = vectors.requestPublicKeyBase64
                )
            )
        }
    }

    @Test
    fun `receipt vectors reproduce canonical result signing input and signature`() {
        for (case in vectors.cases) {
            val request = MeshRequest.decodedFromEnvelope(case.requestEnvelopeBase64)
            val receipt = MeshReceipt.decodedFromEnvelope(case.receiptEnvelopeBase64)

            assertEquals(case.receiptCanonicalResult, MeshReceipt.canonicalResultString(receipt.result), case.name)
            assertEquals(case.receiptSigningInput, receipt.signingInput(), case.name)

            val resigned = MeshReceiptSigner.ed25519(vectors.receiptKeyId, vectors.receiptSeed).makeReceipt(
                receiptId = receipt.receiptId,
                request = request,
                targetAppId = receipt.targetAppId,
                targetBundleId = receipt.targetBundleId,
                status = receipt.status,
                result = receipt.result,
                nonce = receipt.nonce,
                timestamp = receipt.timestamp
            )
            assertEquals(case.receiptSigningInput, resigned.signingInput(), case.name)
            assertTrue(
                Ed25519Jvm.rawKeyVerifier.verify(
                    resigned.signingInputData(),
                    Base64.getDecoder().decode(resigned.signature.value),
                    Base64.getDecoder().decode(vectors.receiptPublicKeyBase64)
                ),
                case.name
            )

            MeshReceiptVerifier.verifyCorrelated(
                receipt,
                request,
                MeshReceiptTrust(
                    targetAppId = receipt.targetAppId,
                    targetBundleId = receipt.targetBundleId,
                    receiptSigningAlgorithm = "Ed25519",
                    receiptSigningKeyId = vectors.receiptKeyId,
                    publicKeyBase64 = vectors.receiptPublicKeyBase64
                ),
                now = java.time.Instant.parse(receipt.timestamp)
            )
        }
    }

    @Test
    fun `kotlin envelope re-encoding round-trips losslessly`() {
        for (case in vectors.cases) {
            val request = MeshRequest.decodedFromEnvelope(case.requestEnvelopeBase64)
            assertEquals(request, MeshRequest.decodedFromEnvelope(request.encodedForEnvelope()), case.name)
            val receipt = MeshReceipt.decodedFromEnvelope(case.receiptEnvelopeBase64)
            assertEquals(receipt, MeshReceipt.decodedFromEnvelope(receipt.encodedForEnvelope()), case.name)
        }
    }
}
